INSERT INTO permissions(code,description,owning_service,sensitive,active) VALUES
('PARENT_COMMUNICATION_USE','Start and participate in authorized parent communication threads','school-service',FALSE,TRUE),
('PARENT_COMMUNICATION_RESPOND','Respond to assigned parent communication threads','school-service',FALSE,TRUE),
('PARENT_COMMUNICATION_MANAGE_CONTACTS','Configure parent-facing school contacts and communication policy','school-service',TRUE,TRUE)
ON CONFLICT(code) DO NOTHING;

INSERT INTO role_permissions(role,permission_id)
SELECT 'PARENT',id FROM permissions WHERE code='PARENT_COMMUNICATION_USE' ON CONFLICT DO NOTHING;

INSERT INTO role_permissions(role,permission_id)
SELECT role_name,p.id FROM (VALUES('ADMIN'),('PRINCIPAL'),('VICE_PRINCIPAL'),('TEACHER'),('ADMISSIONS_OFFICER'),('EXAMINATION_CONTROLLER'),('LIBRARIAN'),('HR'),('ACCOUNTANT'),('TRANSPORT_MANAGER'),('HOSTEL_STAFF'),('INVENTORY_MANAGER'),('SPORTS_STAFF'),('SCIENCE_LAB_STAFF'),('COMPUTER_LAB_STAFF'),('MUSIC_STAFF')) roles(role_name)
CROSS JOIN permissions p WHERE p.code='PARENT_COMMUNICATION_RESPOND' ON CONFLICT DO NOTHING;

INSERT INTO role_permissions(role,permission_id)
SELECT role_name,p.id FROM (VALUES('ADMIN'),('PRINCIPAL'),('VICE_PRINCIPAL')) roles(role_name)
CROSS JOIN permissions p WHERE p.code='PARENT_COMMUNICATION_MANAGE_CONTACTS' ON CONFLICT DO NOTHING;

ALTER TABLE notification_events DROP CONSTRAINT chk_notification_events_type;
ALTER TABLE notification_events ADD CONSTRAINT chk_notification_events_type CHECK(event_type IN (
 'DEVELOPMENT_SAMPLE','COVER_NEEDED','APPROVAL_REQUIRED','CONFIRMED_SUBSTITUTION','IMMINENT_UNCOVERED','CLASS_UNCOVERED','COVER_CHANGED','ATTENDANCE_RECORDED','ATTENDANCE_CORRECTED','RESULT_PUBLISHED','REPORT_CARD_PUBLISHED','SECURITY_ALERT','ACCOUNT_LOCKED','ACCOUNT_STATUS_CHANGED','ROLE_ASSIGNMENT_REQUESTED','ROLE_ASSIGNMENT_APPROVAL_REQUIRED','ROLE_ASSIGNMENT_APPROVED','ROLE_ASSIGNMENT_REJECTED','ROLE_ASSIGNMENT_CANCELLED','ROLE_REMOVAL_REQUESTED','ROLE_REMOVAL_APPROVAL_REQUIRED','ROLE_REMOVAL_APPROVED','ROLE_REMOVAL_REJECTED','ROLE_REMOVAL_CANCELLED','SCHOOL_ANNOUNCEMENT','DAWNRISE_RELEASE','LEAVE_REQUESTED','LEAVE_APPROVAL_REQUIRED','LEAVE_APPROVED','LEAVE_REJECTED','LEAVE_WITHDRAWN','LEAVE_CANCELLED','LEAVE_CHANGED','STUDENT_LEAVE_REQUESTED','STUDENT_LEAVE_APPROVAL_REQUIRED','STUDENT_LEAVE_GUARDIAN_APPROVAL_REQUIRED','STUDENT_LEAVE_SCHOOL_APPROVAL_REQUIRED','STUDENT_LEAVE_RETURNED','STUDENT_LEAVE_RESUBMITTED','STUDENT_LEAVE_APPROVED','STUDENT_LEAVE_REJECTED','STUDENT_LEAVE_WITHDRAWN','STUDENT_LEAVE_CANCELLED','STUDENT_LEAVE_CHANGED','SCHOOL_PROVISIONING_COMPLETED','SCHOOL_PROVISIONING_FAILED','TIMETABLE_PUBLISHED','TIMETABLE_CHANGED','TIMETABLE_EXPIRING','TIMETABLE_EXPIRES_TODAY','EXAM_SCHEDULE_PUBLISHED','LEAVE_POLICY_CREATED','LEAVE_POLICY_RETIRED','PARENT_COMMUNICATION_MESSAGE'));
ALTER TABLE notification_events DROP CONSTRAINT chk_notification_events_action;
ALTER TABLE notification_events ADD CONSTRAINT chk_notification_events_action CHECK(action_type IN ('NONE','DAILY_COVERAGE','TIMETABLE','EXAMINATION','ATTENDANCE','PUBLISHED_RESULT','REPORT_CARD','ACCOUNT_SECURITY','SETTINGS','ROLE_REQUEST','ANNOUNCEMENT','RELEASE_DETAILS','LEAVE_REQUEST','LEAVE_POLICY','COMMUNICATION_THREAD'));
